<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TaskFlow</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#172033;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1100px;margin:auto;padding:34px 20px}.top{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:28px}.eyebrow{color:#3157d5;text-transform:uppercase;font-weight:800;letter-spacing:.12em;font-size:.75rem}h1{font-size:clamp(2rem,5vw,3.6rem);margin:.2rem 0}.muted{color:#68748a}.panel,.card{background:#fff;border:1px solid #e3e9f2;border-radius:18px;box-shadow:0 8px 28px #1d35570b}.panel{padding:20px;margin-bottom:24px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:6px}.full{grid-column:1/-1}label{font-size:.82rem;font-weight:700;color:#536177}input,select,textarea{border:1px solid #d6deea;border-radius:10px;padding:11px;font:inherit;background:#fbfcfe}textarea{min-height:90px;resize:vertical}button{border:0;border-radius:10px;padding:11px 16px;font-weight:800;cursor:pointer}.primary{background:#3157d5;color:#fff}.danger{background:#fff0f0;color:#b42318}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:15px}.card{padding:18px}.card h3{margin:0 0 8px}.meta{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.tag{font-size:.75rem;padding:5px 9px;border-radius:999px;background:#eef2ff;color:#3157d5;font-weight:700}.tag.high{background:#fff1e8;color:#bc5b00}.tag.done{background:#e8f8ee;color:#137a3b}.actions{display:flex;gap:8px}.notice{padding:12px 15px;background:#e8f8ee;color:#137a3b;border-radius:10px;margin-bottom:18px}.errors{color:#b42318;margin:0 0 16px;padding-left:20px}@media(max-width:650px){.top{display:block}.grid{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><header class="top"><div><div class="eyebrow">TaskFlow · Laravel + MySQL</div><h1>Make progress visible.</h1><p class="muted">A focused task board for planning, prioritising and finishing work.</p></div><a href="https://github.com/saidelkhoudar/taskflow-laravel" class="muted">View source ↗</a></header>
