<section class="panel"><form method="POST" action="{{ route('tasks.store') }}">@csrf<div class="grid"><div class="field full"><label for="title">New task</label><input id="title" name="title" maxlength="120" required placeholder="What needs to be done?"></div><div class="field"><label for="priority">Priority</label><select id="priority" name="priority"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></div><div class="field"><label for="due_date">Due date</label><input id="due_date" name="due_date" type="date"></div><div class="field full"><label for="description">Notes</label><textarea id="description" name="description" maxlength="2000" placeholder="Optional context"></textarea></div><input type="hidden" name="status" value="todo"><div class="full"><button class="primary">Add task</button></div></div></form></section>
<section class="panel"><form method="GET" class="grid"><div class="field"><label for="q">Search</label><input id="q" name="q" value="{{ $filters['q'] ?? '' }}" placeholder="Title or notes"></div><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option>@foreach(['todo'=>'To do','in_progress'=>'In progress','done'=>'Done'] as $value=>$label)<option value="{{ $value }}" @selected(($filters['status'] ?? '')===$value)>{{ $label }}</option>@endforeach</select></div><div class="full"><button class="primary">Filter tasks</button> <a href="{{ route('tasks.index') }}" class="muted">Reset</a></div></form></section>
<div class="cards">@forelse($tasks as $task)<article class="card"><h3>{{ $task->title }}</h3><p class="muted">{{ $task->description ?: 'No notes added.' }}</p><div class="meta"><span class="tag {{ $task->priority === 'high' ? 'high' : '' }}">{{ ucfirst($task->priority) }}</span><span class="tag {{ $task->status === 'done' ? 'done' : '' }}">{{ str_replace('_',' ',ucfirst($task->status)) }}</span>@if($task->due_date)<span class="tag">Due {{ $task->due_date->format('M j, Y') }}</span>@endif</div><div class="actions"><form method="POST" action="{{ route('tasks.update',$task) }}">@csrf @method('PUT')<input type="hidden" name="title" value="{{ $task->title }}"><input type="hidden" name="description" value="{{ $task->description }}"><input type="hidden" name="priority" value="{{ $task->priority }}"><input type="hidden" name="due_date" value="{{ optional($task->due_date)->format('Y-m-d') }}"><input type="hidden" name="status" value="{{ $task->status === 'done' ? 'todo' : 'done' }}"><button class="primary">{{ $task->status === 'done' ? 'Reopen' : 'Complete' }}</button></form><form method="POST" action="{{ route('tasks.destroy',$task) }}">@csrf @method('DELETE')<button class="danger">Delete</button></form></div></article>@empty<div class="card"><h3>No tasks yet</h3><p class="muted">Create your first task above.</p></div>@endforelse</div><div style="margin-top:20px">{{ $tasks->links() }}</div></main></body></html>
